create extension if not exists pgcrypto;

create table if not exists public.roles (id uuid primary key default gen_random_uuid(), name text not null unique, description text not null, created_at timestamptz not null default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, role_id uuid not null references public.roles(id), full_name text not null, email text not null unique, initials text not null, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.clients (id uuid primary key default gen_random_uuid(), name text not null, industry text not null, status text not null check (status in ('Active','On hold','Archived')), location text not null, description text not null, primary_manager_id uuid references public.profiles(id), document_count integer not null default 0, outstanding_requests integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.client_contacts (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, full_name text not null, email text not null, phone text not null, is_primary boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.engagements (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), name text not null, service_type text not null, period_label text not null, status text not null, manager_id uuid not null references public.profiles(id), deadline date not null, progress integer not null default 0 check (progress between 0 and 100), document_count integer not null default 0, outstanding_documents integer not null default 0, review_note text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.engagement_members (engagement_id uuid not null references public.engagements(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, primary key (engagement_id, profile_id));
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(), engagement_id uuid not null references public.engagements(id) on delete cascade, title text not null, description text not null, assigned_to uuid not null references public.profiles(id), priority text not null, due_date date not null, status text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.task_comments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null, created_at timestamptz not null default now());
create table if not exists public.documents (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), engagement_id uuid not null references public.engagements(id), name text not null, document_type text not null, status text not null, storage_path text, uploaded_by uuid references public.profiles(id), uploaded_at timestamptz not null default now());
create table if not exists public.quotations (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), service_type text not null, description text not null, terms text not null, status text not null, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.quotation_items (id uuid primary key default gen_random_uuid(), quotation_id uuid not null references public.quotations(id) on delete cascade, description text not null, quantity numeric(10,2) not null, unit_price numeric(14,2) not null);
create table if not exists public.reports (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id), engagement_id uuid not null references public.engagements(id), report_type text not null, status text not null, content_json jsonb, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.activity_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), event_type text not null, description text not null, record_type text not null, record_id uuid not null, created_at timestamptz not null default now());
create table if not exists public.ai_conversations (id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), title text, created_at timestamptz not null default now());
create table if not exists public.ai_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.ai_conversations(id) on delete cascade, role text not null check (role in ('system','user','assistant','tool')), content text not null, created_at timestamptz not null default now());
create table if not exists public.ai_actions (id uuid primary key default gen_random_uuid(), conversation_id uuid references public.ai_conversations(id), tool_name text not null, input_json jsonb, result_summary text, created_at timestamptz not null default now());

create index if not exists idx_clients_status on public.clients(status);
create index if not exists idx_engagements_deadline on public.engagements(deadline);
create index if not exists idx_tasks_due_status on public.tasks(due_date, status);
create index if not exists idx_tasks_assigned_to on public.tasks(assigned_to);
create index if not exists idx_activity_created_at on public.activity_logs(created_at desc);

alter table public.roles enable row level security;
alter table public.profiles enable row level security;
alter table public.clients enable row level security;
alter table public.client_contacts enable row level security;
alter table public.engagements enable row level security;
alter table public.engagement_members enable row level security;
alter table public.tasks enable row level security;
alter table public.task_comments enable row level security;
alter table public.documents enable row level security;
alter table public.quotations enable row level security;
alter table public.quotation_items enable row level security;
alter table public.reports enable row level security;
alter table public.activity_logs enable row level security;
alter table public.ai_conversations enable row level security;
alter table public.ai_messages enable row level security;
alter table public.ai_actions enable row level security;

create policy "authenticated users can read roles" on public.roles for select to authenticated using (true);
create policy "authenticated users can read workspace records" on public.clients for select to authenticated using (true);
create policy "authenticated users can read client contacts" on public.client_contacts for select to authenticated using (true);
create policy "authenticated users can read engagements" on public.engagements for select to authenticated using (true);
create policy "authenticated users can read engagement members" on public.engagement_members for select to authenticated using (true);
create policy "authenticated users can read tasks" on public.tasks for select to authenticated using (true);
create policy "authenticated users can read task comments" on public.task_comments for select to authenticated using (true);
create policy "authenticated users can read documents" on public.documents for select to authenticated using (true);
create policy "authenticated users can read quotations" on public.quotations for select to authenticated using (true);
create policy "authenticated users can read quotation items" on public.quotation_items for select to authenticated using (true);
create policy "authenticated users can read reports" on public.reports for select to authenticated using (true);
create policy "authenticated users can read activity" on public.activity_logs for select to authenticated using (true);
create policy "authenticated users can read own profile" on public.profiles for select to authenticated using (id = auth.uid());
create policy "authenticated users can read own ai conversations" on public.ai_conversations for select to authenticated using (profile_id = auth.uid());
create policy "authenticated users can manage own ai conversations" on public.ai_conversations for all to authenticated using (profile_id = auth.uid()) with check (profile_id = auth.uid());
create policy "authenticated users can manage messages in own conversations" on public.ai_messages for all to authenticated using (exists (select 1 from public.ai_conversations c where c.id = conversation_id and c.profile_id = auth.uid())) with check (exists (select 1 from public.ai_conversations c where c.id = conversation_id and c.profile_id = auth.uid()));
create policy "authenticated users can read actions in own conversations" on public.ai_actions for select to authenticated using (exists (select 1 from public.ai_conversations c where c.id = conversation_id and c.profile_id = auth.uid()));
